import React from "react";

const features = [
  {
    title: "Modelos Meteorológicos",
    description: "Visualiza pronósticos avanzados y mapas interactivos del clima en tu región.",
    icon: "🌦️",
  },
  {
    title: "Monitoreo de Gases",
    description: "Consulta datos en tiempo real sobre la calidad del aire y gases atmosféricos.",
    icon: "🫧",
  },
  {
    title: "Alertas y Riesgos",
    description: "Recibe alertas sobre incendios, tormentas y condiciones extremas.",
    icon: "⚠️",
  },
  {
    title: "Acceso Móvil",
    description: "Plataforma optimizada para dispositivos móviles y tablets.",
    icon: "📱",
  },
];

export default function Landing() {
  return (
    <div className="min-h-screen flex flex-col bg-gradient-to-b from-blue-900 via-blue-200 to-white">
      {/* Header */}
      <header className="w-full py-6 px-4 flex justify-between items-center bg-blue-900 shadow-md">
        <div className="flex items-center space-x-3">
          <img src="/favicon.svg" alt="Logo" className="h-10 w-10" />
          <span className="text-2xl font-bold text-white tracking-wide">Observatorio Hidrometeorológico</span>
        </div>
        <a href="/" className="text-blue-100 hover:text-white font-medium transition">Ingresar</a>
      </header>

      {/* Hero Section */}
      <section className="flex flex-col md:flex-row items-center justify-between px-6 md:px-16 py-12 md:py-24 gap-10">
        <div className="flex-1 space-y-6">
          <h1 className="text-4xl md:text-6xl font-extrabold text-blue-900 leading-tight">
            Tu portal de <span className="text-blue-500">clima</span> y <span className="text-blue-400">productos meteorológicos</span>
          </h1>
          <p className="text-lg md:text-xl text-blue-800 max-w-xl">
            Accede a pronósticos, mapas interactivos, monitoreo ambiental y alertas en tiempo real. Todo en una sola plataforma, desde cualquier dispositivo.
          </p>
          <a href="/" className="inline-block bg-blue-600 hover:bg-blue-700 text-white font-semibold px-8 py-3 rounded-lg shadow-lg transition text-lg">Explorar Dashboard</a>
        </div>
        <div className="flex-1 flex justify-center">
          <img src="/fondo-cielo.png" alt="Clima" className="rounded-3xl shadow-2xl w-full max-w-md object-cover" />
        </div>
      </section>

      {/* Features */}
      <section className="py-12 px-4 md:px-16 bg-white/80">
        <h2 className="text-3xl md:text-4xl font-bold text-blue-900 text-center mb-10">¿Qué puedes hacer aquí?</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-8 max-w-5xl mx-auto">
          {features.map((f, i) => (
            <div key={i} className="bg-white rounded-2xl shadow-lg p-6 flex flex-col items-center text-center border border-blue-100 hover:shadow-xl transition">
              <div className="text-5xl mb-4">{f.icon}</div>
              <h3 className="text-xl font-semibold text-blue-800 mb-2">{f.title}</h3>
              <p className="text-blue-700 text-base">{f.description}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Call to Action */}
      <section className="py-12 px-4 md:px-0 flex flex-col items-center bg-gradient-to-t from-blue-100 to-white">
        <h2 className="text-2xl md:text-3xl font-bold text-blue-900 mb-4">¿Listo para comenzar?</h2>
        <a href="/" className="bg-blue-600 hover:bg-blue-700 text-white font-semibold px-8 py-3 rounded-lg shadow-lg transition text-lg">Ir al Dashboard</a>
      </section>

      {/* Footer */}
      <footer className="mt-auto py-6 px-4 bg-blue-900 text-blue-100 text-center text-sm">
        &copy; {new Date().getFullYear()} Observatorio Hidrometeorológico. Todos los derechos reservados.
      </footer>
    </div>
  );
}
